import 'dart:io';
import 'package:flutter/material.dart';
import 'package:supabase_flutter/supabase_flutter.dart';
import 'package:device_info_plus/device_info_plus.dart';

const supabaseUrl = 'https://figpskarzodfeiaulmfa.supabase.co';
const supabaseKey = 'sb_publishable_OlHhzoYHI7lz84y-LSNFOg_S0s3EH0C';

void main() async {
  WidgetsFlutterBinding.ensureInitialized();
    await Supabase.initialize(url: supabaseUrl, anonKey: supabaseKey);
      runApp(const RewardApp());
      }

      class RewardApp extends StatelessWidget {
        const RewardApp({super.key});

          @override
            Widget build(BuildContext context) {
                return MaterialApp(
                      title: 'Task Rewards',
                            theme: ThemeData(primarySwatch: Colors.blue),
                                  home: const AuthWrapper(),
                                        debugShowCheckedModeBanner: false,
                                            );
                                              }
                                              }

                                              // 1. Auth Wrapper to check if user is logged in
                                              class AuthWrapper extends StatefulWidget {
                                                const AuthWrapper({super.key});

                                                  @override
                                                    State<AuthWrapper> createState() => _AuthWrapperState();
                                                    }

                                                    class _AuthWrapperState extends State<AuthWrapper> {
                                                      @override
                                                        void initState() {
                                                            super.initState();
                                                                Supabase.instance.client.auth.onAuthStateChange.listen((data) {
                                                                      if (mounted) setState(() {});
                                                                          });
                                                                            }

                                                                              @override
                                                                                Widget build(BuildContext context) {
                                                                                    final session = Supabase.instance.client.auth.currentSession;
                                                                                        if (session == null) {
                                                                                              return const LoginScreen();
                                                                                                  }
                                                                                                      return const EarnScreen();
                                                                                                        }
                                                                                                        }

                                                                                                        // 2. Login & Signup Screen with Device Check
                                                                                                        class LoginScreen extends StatefulWidget {
                                                                                                          const LoginScreen({super.key});

                                                                                                            @override
                                                                                                              State<LoginScreen> createState() => _LoginScreenState();
                                                                                                              }

                                                                                                              class _LoginScreenState extends State<LoginScreen> {
                                                                                                                final _emailController = TextEditingController();
                                                                                                                  final _passwordController = TextEditingController();
                                                                                                                    final _supabase = Supabase.instance.client;
                                                                                                                      bool isLoginMode = true;
                                                                                                                        bool isLoading = false;

                                                                                                                          Future<String?> _getDeviceHardwareId() async {
                                                                                                                              final deviceInfo = DeviceInfoPlugin();
                                                                                                                                  if (Platform.isAndroid) {
                                                                                                                                        final androidInfo = await deviceInfo.androidInfo;
                                                                                                                                              return androidInfo.id;
                                                                                                                                                  } else if (Platform.isIOS) {
                                                                                                                                                        final iosInfo = await deviceInfo.iosInfo;
                                                                                                                                                              return iosInfo.identifierForVendor;
                                                                                                                                                                  }
                                                                                                                                                                      return 'unknown_device';
                                                                                                                                                                        }

                                                                                                                                                                          Future<void> _authenticate() async {
                                                                                                                                                                              setState(() => isLoading = true);
                                                                                                                                                                                  try {
                                                                                                                                                                                        final email = _emailController.text.trim();
                                                                                                                                                                                              final password = _passwordController.text.trim();
                                                                                                                                                                                                    final deviceId = await _getDeviceHardwareId();

                                                                                                                                                                                                          if (email.isEmpty || password.isEmpty) {
                                                                                                                                                                                                                  throw 'Please fill in all fields';
                                                                                                                                                                                                                        }

                                                                                                                                                                                                                              if (isLoginMode) {
                                                                                                                                                                                                                                      // --- LOGIN FLOW ---
                                                                                                                                                                                                                                              final response = await _supabase.auth.signInWithPassword(email: email, password: cmakeEmailCleanup(password));
                                                                                                                                                                                                                                                      final userId = response.user?.id;

                                                                                                                                                                                                                                                              if (userId != null) {
                                                                                                                                                                                                                                                                        // Check if device matches bound device
                                                                                                                                                                                                                                                                                  final userRecord = await _supabase.from('users').select().eq('id', userId).maybeSingle();
                                                                                                                                                                                                                                                                                            if (userRecord != null && userRecord['device_id'] != null && userRecord['device_id'] != deviceId) {
                                                                                                                                                                                                                                                                                                        await _supabase.auth.signOut();
                                                                                                                                                                                                                                                                                                                    throw 'Access Denied: This account is linked to another device.';
                                                                                                                                                                                                                                                                                                                              }
                                                                                                                                                                                                                                                                                                                                      }
                                                                                                                                                                                                                                                                                                                                            } else {
                                                                                                                                                                                                                                                                                                                                                    // --- SIGNUP FLOW (1 Account Per Device Check) ---
                                                                                                                                                                                                                                                                                                                                                            // 1. Check if this physical device ID already exists in the users table
                                                                                                                                                                                                                                                                                                                                                                    final existingDeviceUser = await _supabase
                                                                                                                                                                                                                                                                                                                                                                                .from('users')
                                                                                                                                                                                                                                                                                                                                                                                            .select()
                                                                                                                                                                                                                                                                                                                                                                                                        .eq('device_id', deviceId!)
                                                                                                                                                                                                                                                                                                                                                                                                                    .maybeSingle();

                                                                                                                                                                                                                                                                                                                                                                                                                            if (existingDeviceUser != null) {
                                                                                                                                                                                                                                                                                                                                                                                                                                      throw 'Multiple accounts on the same device are not allowed!';
                                                                                                                                                                                                                                                                                                                                                                                                                                              }

                                                                                                                                                                                                                                                                                                                                                                                                                                                      // 2. Register account in Supabase Auth
                                                                                                                                                                                                                                                                                                                                                                                                                                                              final response = await _supabase.auth.signUp(email: email, password: password);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                      final userId = response.user?.id;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                              if (userId != null) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        // 3. Create user profile row and lock it to this device ID
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  await _supabase.from('users').insert({
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              'id': userId,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          'email': email,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      'device_id': deviceId,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  'coin_balance': 0,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              } catch (e) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    ScaffoldMessenger.of(context).showSnackBar(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            SnackBar(content: Text(e.toString().replaceAll('Exception: ', ''))),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      } finally {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            setState(() => isLoading = false);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    String cmakeEmailCleanup(String val) => val;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      @override
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        Widget build(BuildContext context) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            return Scaffold(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  appBar: AppBar(title: Text(isLoginMode ? 'Login to Existing Account' : 'Create New Account')),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        body: Padding(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                padding: const EdgeInsets.all(24.0),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        child: Column(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  mainAxisAlignment: MainAxisAlignment.center,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            children: [
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        TextField(controller: _emailController, decoration: const InputDecoration(labelText: 'Email Address')),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    const SizedBox(height: 12),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                TextField(controller: _passwordController, obscureText: true, decoration: const InputDecoration(labelText: 'Password')),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            const SizedBox(height: 24),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        isLoading
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        ? const CircularProgressIndicator()
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        : ElevatedButton(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            onPressed: _authenticate,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                child: Text(isLoginMode ? 'Login' : 'Sign Up'),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  ),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              TextButton(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            onPressed: () => setState(() => isLoginMode = !isLoginMode),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          child: Text(isLoginMode ? "Don't have an account? Sign Up" : 'Already have an account? Login'),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      ),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                ],
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        ),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              ),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    // 3. Main Dashboard for Authenticated User
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    class EarnScreen extends StatefulWidget {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      const EarnScreen({super.key});

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        @override
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          State<EarnScreen> createState() => _EarnScreenState();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          class _EarnScreenState extends State<EarnScreen> {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            final _supabase = Supabase.instance.client;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              @override
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                Widget build(BuildContext context) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    final user = _supabase.auth.currentUser;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        return Scaffold(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              appBar: AppBar(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      title: const Text('Earn Coins'),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              actions: [
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        IconButton(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    icon: const Icon(Icons.logout),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                onPressed: () => _supabase.auth.signOut(),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  ],
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        ),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              body: ListView(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      padding: const EdgeInsets.all(16.0),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              children: [
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        StreamBuilder<List<Map<String, dynamic>>>(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    stream: _supabase.from('users').stream(primaryKey: ['id']).eq('id', user!.id),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                builder: (context, snapshot) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              if (snapshot.hasError) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              return Card(child: Padding(padding: const EdgeInsets.all(16.0), child: Text('Error: ${snapshot.error}')));
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          if (!snapshot.hasData || snapshot.data!.isEmpty) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          return const Card(child: Padding(padding: EdgeInsets.all(24.0), child: Center(child: CircularProgressIndicator())));
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      final balance = snapshot.data!.first['coin_balance'] ?? 0;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    return Card(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    color: Colors.blueAccent,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    child: Padding(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      padding: const EdgeInsets.all(24.0),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        child: Column(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            children: [
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  const Text('Your Account Balance', style: TextStyle(color: Colors.white, fontSize: 16)),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        const SizedBox(height: 8),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              Text('$balance Coins', style: const TextStyle(color: Colors.white, fontSize: 32, fontWeight: FontWeight.bold)),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    const SizedBox(height: 4),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          Text('Email: ${user.email}', style: const TextStyle(color: Colors.white70, fontSize: 11)),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              ],
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                ),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                ),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    ),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              const SizedBox(height: 20),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        ElevatedButton.icon(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    icon: const Icon(Icons.video_library),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                label: const Text('Watch Ad (+10 Coins)'),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            onPressed: () async {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          try {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          final currentResp = await _supabase.from('users').select('coin_balance').eq('id', user.id).single();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          int currentBalance = currentResp['coin_balance'] ?? 0;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          
